class VersionInfo:
    def __init__(self, major, minor, patch, prerelease=None, build=None):
        self._major = int(major)
        self._minor = int(minor)
        self._patch = int(patch)
        self._prerelease = str(prerelease) if prerelease else None
        self._build = str(build) if build else None

    @property
    def major(self):
        return self._major

    @property
    def minor(self):
        return self._minor

    @property
    def patch(self):
        return self._patch

    @property
    def prerelease(self):
        return self._prerelease

    @property
    def build(self):
        return self._build

    def __iter__(self):
        yield from [self.major, self.minor, self.patch, self.prerelease, self.build]

    def __eq__(self, other):
        if not isinstance(other, tuple):
            raise TypeError('VersionInfo can only be compared with tuples')
        return self.major == other[0] and self.minor == other[1] and self.patch == other[2] and self.prerelease == other[3] and self.build == other[4]

    def bump_major(self):
        return VersionInfo(self.major + 1, 0, 0, self.prerelease, self.build)

    def bump_minor(self):
        return VersionInfo(self.major, self.minor + 1, 0, self.prerelease, self.build)

    def bump_patch(self):
        return VersionInfo(self.major, self.minor, self.patch + 1, self.prerelease, self.build)

    def bump_prerelease(self):
        if self.prerelease is None:
            return VersionInfo(self.major, self.minor, self.patch, '0', self.build)
        else:
            prerelease_parts = list(map(int, self.prerelease.split('.')))
            prerelease_parts[-1] += 1
            return VersionInfo(self.major, self.minor, self.patch, '.'.join(map(str, prerelease_parts)), self.build)

    def bump_build(self):
        if self.build is None:
            return VersionInfo(self.major, self.minor, self.patch, self.prerelease, '0')
        else:
            build_parts = list(map(int, self.build.split('.')))
            build_parts[-1] += 1
            return VersionInfo(self.major, self.minor, self.patch, self.prerelease, '.'.join(map(str, build_parts)))

    def replace(self, **kwargs):
        new_version = VersionInfo(self.major, self.minor, self.patch, self.prerelease, self.build)
        for key, value in kwargs.items():
            if hasattr(new_version, key):
                setattr(new_version, key, value)
        return new_version

